 // --- Pipeline tracking (nullable, for standalone/pipeline separation) ---\n  runId               Int?\n  run                 WorkflowRun?               @relation(fields: [runId], references: [id], onDelete: SetNull)\n  pipelineId          Int?\n  pipeline            Pipeline?                  @relation(fields: [pipelineId], references: [id], onDelete: SetNull)\n  variants            ScenarioVariant[]\n  reviewActions       ScenarioReviewAction[]\n  videos              Video[]\n  feedbacks           ScenarioFeedback[]\n  criticReviews       CriticReview[]\n\n  @@index([trendId, isDeleted])\n  @@index([status, isDeleted])\n  @@index([runId])\n  @@index([pipelineId])\n  @@index([sceneId])\n}\n\nmodel ScenarioVariant {\n  id                    Int                     @id @default(autoincrement())\n  scenarioId            Int\n  scenario              Scenario                @relation(fields: [scenarioId], references: [id], onDelete: Cascade)\n  variantIndex          Int\n  status                VariantStatus           @default(draft)\n  title                 String\n  hook                  String\n  body                  String\n  cta                   String\n  fullScript            String\n  visualStyleText       String\n  visualStyleStructured Json?\n  storyPlan             Json? // StoryPlan structured output\n  qualityScore          Float?\n  qualityScoreDetails   Json? // VariantQualityScore целиком\n  qualityCheckedAt      DateTime?\n  toneProfile           String?\n  rationale             String?\n  promptVersion         String?\n  agentVersion          String?\n  isDeleted             Boolean                 @default(false)\n  deletedAt             DateTime?\n  createdAt             DateTime                @default(now())\n  updatedAt             DateTime                @updatedAt\n  blockRevisions        ScenarioBlockRevision[]\n  visualStyleRevisions  VisualStyleRevision[]\n  reviewActions         ScenarioReviewAction[]\n\n  @@index([scenarioId, status])\n}\n\nmodel ScenarioBlockRevision {\n  id        Int             @id @default(autoincrement())\n  variantId Int\n  variant   ScenarioVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  blockType String\n  oldValue  String\n  newValue  String\n  reason    String?\n  createdAt DateTime        @default(now())\n\n  @@index([variantId, blockType])\n}\n\nmodel VisualStyleRevision {\n  id             Int             @id @default(autoincrement())\n  variantId      Int\n  variant        ScenarioVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  colors         Json?\n  atmosphere     String?\n  character      String?\n  stylePrompt    String?\n  improvedPrompt String?\n  source         String?\n  createdAt      DateTime        @default(now())\n\n  @@index([variantId])\n}\n\nmodel ScenarioReviewAction {\n  id         Int              @id @default(autoincrement())\n  scenarioId Int\n  scenario   Scenario         @relation(fields: [scenarioId], references: [id], onDelete: Cascade)\n  variantId  Int?\n  variant    ScenarioVariant? @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  actionType ReviewActionType\n  reason     String?\n  createdAt  DateTime         @default(now())\n\n  @@index([scenarioId, createdAt])\n}\n\nmodel Video {\n  id                       Int                   @id @default(autoincrement())\n  scenarioId               Int\n  scenario                 Scenario              @relation(fields: [scenarioId], references: [id], onDelete: Cascade)\n  variantId                Int?\n  applicationId            Int?\n  status                   VideoStatus           @default(pending)\n  currentStep              String?\n  format                   VideoFormat           @default(portrait)\n  filePath                 String?\n  fileUrl                  String?\n  // GCS persistent storage (Saturn PaaS лишён persistent volume для ./storage,\n  // поэтому финальное видео живёт в bucket marketingcamp-creatives под префиксом\n  // zavodcamp/. filePath/fileUrl остаются ещё ~2 недели для backward compat —\n  // потом отдельная микро-миграция DROP COLUMN).\n  storageKey               String?\n  storageProvider          String                @default(\"gcs\")\n  fileSizeBytes            BigInt?\n  fileSha256               String?\n  duration                 Int?\n  errorMessage             String?\n  // Output configuration\n  subtitlesEnabled         Boolean               @default(true)\n  subtitlesStyle           Json?\n  // Brand-safe preset субтитров: tiktok_classic | tiktok_bold_yellow | tiktok_boxed | minimal.\n  // null = применяется дефолт рендера (tiktok_classic).\n  subtitlePreset           String?\n  voiceoverPlan            Json? // VoiceoverPlan structured output\n  musicEnabled             Boolean               @default(true)\n  musicMood                String?\n  musicDuration            Int?\n  musicVolume              Float                 @default(0.3)\n  musicVolumeWithVoiceover Float                 @default(0.12)\n  clipDuration             Int                   @default(5)\n  imageCount               Int                   @default(3)\n  renderQuality            String                @default(\"medium\")\n  targetPlatform           String?\n  // Voiceover / TTS configuration\n  voiceoverEnabled         Boolean               @default(false)\n  voiceoverProvider        String?\n  voiceoverModelId         String?\n  voiceoverVoiceId         String?\n  voiceoverLanguage        String                @default(\"en\")\n  voiceoverPacing          String                @default(\"moderate\")\n  voiceoverReconciliation  String                @default(\"extend_scene\")\n  // Model selection (runtime uses these, not hardcodes)\n  imageModelId             String                @default(\"fal-ai/flux/dev\")\n  videoModelId             String                @default(\"fal-ai/kling-video/v3/standard/text-to-video\")\n  modelStrategy            String                @default(\"auto\")\n  generateAudio            Boolean               @default(true)\n  // Lip-sync (premium feature, gated by quality preset)\n  lipSyncEnabled           Boolean               @default(false)\n  lipSyncModelId           String?\n  // Job safety\n  isLocked                 Boolean               @default(false)\n  lockedAt                 DateTime?\n  lockedReason             String?\n  startedAt                DateTime?\n  finishedAt               DateTime?\n  // Cost tracking\n  totalCostEstimate        Float?\n  totalCostActual          Float?\n  createdAt                DateTime              @default(now())\n  updatedAt                DateTime              @updatedAt\n  // --- Pipeline tracking (nullable, for standalone/pipeline separation) ---\n  runId                    Int?\n  run                      WorkflowRun?          @relation(fields: [runId], references: [id], onDelete: SetNull)\n  pipelineId               Int?\n  pipeline                 Pipeline?             @relation(fields: [pipelineId], references: [id], onDelete: SetNull)\n  assets                   VideoAsset[]\n  uploads                  Upload[]\n  steps                    VideoGenerationStep[]\n  mediaPredictions         MediaPrediction[]\n  postingJobs              PostingJob[]\n  uniqueVariants           VideoUniqueVariant[]\n  captions                 Caption[]\n  // External creative source (Google Drive, future YouTube/etc.)\n  isExternalCreative       Boolean               @default(false)\n  externalSource           String?\n  externalSourceId         String?\n  driveFile                DriveFile?            @relation(\"DriveFileVideo\")\n  driveFileId              String?\n  driveCredentialId        Int?\n  driveCredential          PipelineCredential?   @relation(\"VideoDriveCredential\", fields: [driveCredentialId], references: [id], onDelete: SetNull)\n  // Marketing-grade frame analysis (Stage 2 of Video Analyzer modernization).\n  // analysisData — JSON snapshot VideoAnalysisFramePass (см. shared/types/video-analysis.ts).\n  // framePassVersion + framePassRunAt — TTL idempotency (default version 'frames-v1', TTL 30 дней).\n  // fitScore/fitRationale — насколько креатив подходит для App (audience+geo+platform).\n  analysisData             Json?\n  framePassVersion         String?\n  framePassRunAt           DateTime?\n  analysisDurationSec      Float?\n  fitScore                 Float?\n  fitRationale             String?\n  frames                   VideoFrame[]\n\n  @@index([scenarioId, status])\n  @@index([status])\n  @@index([runId])\n  @@index([pipelineId])\n  @@index([externalSource, externalSourceId])\n  @@index([framePassRunAt])\n  @@index([storageProvider])\n}\n\n/// Per-frame DB row для marketing-grade анализа видео.\n/// Создаётся в analyzeCreativeVideo после ffmpeg extraction.\n/// description/keyElements заполняются после AI batch (backfill из MarketingFrameAnalysis.frameDescriptions).\nmodel VideoFrame {\n  id              Int      @id @default(autoincrement())\n  videoId         Int\n  video           Video    @relation(fields: [videoId], references: [id], onDelete: Cascade)\n  sequence        Int\n  timestampSec    Float\n  filePath        String\n  width           Int?\n  height          Int?\n  isSceneBoundary Boolean  @default(false)\n  description     String?\n  keyElements     Json?\n  createdAt       DateTime @default(now())\n\n  @@unique([videoId, sequence])\n  @@index([videoId])\n}\n\nmodel VideoAsset {\n  id                       Int               @id @default(autoincrement())\n  videoId                  Int\n  video                    Video             @relation(fields: [videoId], references: [id], onDelete: Cascade)\n  type                     AssetType\n  prompt                   String?\n  filePath                 String?\n  fileUrl                  String?\n  // order — стабильный sceneIndex для type=image|clip (порядок сцены).\n  // Для других типов (music, voiceover, voiceover_mix, thumbnail, preview) order=0.\n  order                    Int               @default(0)\n  duration                 Int?\n  // GCS persistent storage (см. Video.storageKey). storageKey null пока asset\n  // не загружен в bucket; после upload — `zavodcamp/videos/{videoId}/...`.\n  storageKey               String?\n  storageProvider          String            @default(\"gcs\")\n  fileSizeBytes            BigInt?\n  fileSha256               String?\n  contentType              String?\n  createdAt                DateTime          @default(now())\n  favoritePromptsFromAsset FavoritePrompt[]\n  mediaPredictions         MediaPrediction[]\n\n  @@index([storageKey])\n  @@index([videoId, type, order])\n}\n\nmodel VideoGenerationStep {\n  id                   Int             @id @default(autoincrement())\n  videoId              Int\n  video                Video           @relation(fields: [videoId], references: [id], onDelete: Cascade)\n  stepKey              VideoStepKey\n  stepIndex            Int\n  status               VideoStepStatus @default(pending)\n  startedAt            DateTime?\n  finishedAt           DateTime?\n  inputSnapshot        Json?\n  outputSnapshot       Json?\n  artifacts            Json?\n  attemptCount         Int             @default(0)\n  maxAttempts          Int             @default(3)\n  estimatedCost        Float?\n  actualCost           Float?\n  logs                 Json?\n  errorMessage         String?\n  // fal.ai tracking\n  falRequestId         String?\n  falEndpoint          String?\n  falQueueStatus       String?\n  falLogsSnapshot      Json?\n  falSubmittedAt       DateTime?\n  falCompletedAt       DateTime?\n  falCanceledAt        DateTime?\n  falWebhookReceivedAt DateTime?\n  falResultUrl         String?\n  falErrorCode         String?\n  falAttemptGroupId    String?\n  // Sub-key для итеративной генерации (clip per scene). Reattach срабатывает только\n  // если subKey совпадает с сохранённым — иначе новый submit (без двойного списания\n  // и без подмены результата от другой сцены тем же step.id).\n  falSubKey            String?\n  createdAt            DateTime        @default(now())\n  updatedAt            DateTime        @updatedAt\n\n  @@index([videoId, stepKey])\n  @@index([falRequestId])\n  @@index([status])\n}\n\n/// Durable record for every paid asynchronous media-provider request.\n/// Input/output snapshots are sanitized before persistence; provider outputs are\n/// copied to ContentFactory storage before a prediction is exposed as complete.\nmodel MediaPrediction {\n  id                       String      @id @default(cuid())\n  videoId                  Int?\n  video                    Video?      @relation(fields: [videoId], references: [id], onDelete: Cascade)\n  videoAssetId             Int?\n  videoAsset               VideoAsset? @relation(fields: [videoAssetId], references: [id], onDelete: Cascade)\n  provider                 String      @default(\"replicate\")\n  capability               String\n  model                    String\n  externalId               String?     @unique\n  idempotencyKey           String      @unique\n  status                   String      @default(\"starting\")\n  inputSnapshot            Json?\n  outputSnapshot           Json?\n  outputUrl                String?\n  persistedStorageKey      String?\n  persistedStorageProvider String?\n  persistedFileSizeBytes   BigInt?\n  persistedFileSha256      String?\n  persistedContentType     String?\n  errorMessage             String?\n  metrics                  Json?\n  submittedAt              DateTime?\n  startedAt                DateTime?\n  completedAt              DateTime?\n  terminalAt               DateTime?\n  webhookReceivedAt        DateTime?\n  createdAt                DateTime    @default(now())\n  updatedAt                DateTime    @updatedAt\n\n  @@index([status, updatedAt])\n  @@index([videoId])\n  @@index([videoAssetId])\n  @@index([provider, externalId])\n}\n\nmodel TrendInsight {\n  id         Int      @id @default(autoincrement())\n  trendId    Int      @unique\n  trend      Trend    @relation(fields: [trendId], references: [id], onDelete: Cascade)\n  whyViral   String\n  patterns   String[]\n  hooks      String[]\n  audience   String?\n  confidence Float?\n  createdAt  DateTime @default(now())\n}\n\nmodel CreativeBrief {\n  id                    Int      @id @default(autoincrement())\n  trendId               Int      @unique\n  trend                 Trend    @relation(fields: [trendId], references: [id], onDelete: Cascade)\n  hookAnalysis          Json\n  sceneStructure        Json\n  visualStyle           Json\n  viralityReasons       Json\n  frameAnalysisSettings Json?\n  summary               String\n  modelVersion          String\n  promptVersion         String\n  confidence            Float?\n  errorMessage          String?\n  createdAt             DateTime @default(now())\n  updatedAt             DateTime @updatedAt\n}\n\nmodel SocialAccount {\n  id                   Int                      @id @default(autoincrement())\n  appId                Int\n  app                  App                      @relation(fields: [appId], references: [id])\n  platform             Platform\n  displayName          String\n  platformUserId       String?\n  platformHandle       String?\n  accessToken          String?\n  refreshToken         String?\n  expiresAt            DateTime?\n  status               AccountStatus            @default(active)\n  // Используется dispatch'ером группы для round-robin отбора (обновляется в executeUploadNode)\n  lastPostedAt         DateTime?\n  // --- Social Automation foundation (iteration 1) ---\n  // Шифрованные login-секреты (AES-256-GCM, формат iv:authTag:ciphertext)\n  loginEmail           String?\n  loginPassword        String?\n  recoveryEmail        String?\n  recoveryPhone        String?\n  twoFASecret          String?\n  // Operator-facing план / заметки (НЕ секрет, в plain)\n  notes                String?\n  // Метаданные аккаунта\n  birthDate            DateTime?\n  registrationSource   RegistrationSource?\n  // Привязка к прокси (один-ко-многим: один прокси может обслуживать несколько аккаунтов)\n  proxyId              String?\n  proxy                Proxy?                   @relation(fields: [proxyId], references: [id], onDelete: SetNull)\n  // Указатель на device profile (DuoPlus / антидетект). Физическая колонка\n  // остаётся \"indigoProfileId\" (Этап 2: @@map/@map rename без DDL).\n  deviceProfileId      String?                  @map(\"indigoProfileId\")\n  // Метод постинга: api (через OAuth токены) или browser_automation (через Indigo+CDP).\n  // Default 'api' - обратная совместимость с existing accounts. Оператор явно переключает\n  // на browser_automation если у аккаунта нет API access (private TikTok etc).\n  postingMethod        SocialPostingMethod      @default(api)\n  // --- Part D: login-check status (заполняется POST /api/accounts/:id/check-login) ---\n  // null = login-check ещё не запускался. После запуска заполняется триплет:\n  //   loginCheckedAt = timestamp когда проверяли\n  //   loginCheckedStatus = true/false результат detect login на главной странице\n  //   loginCheckedUsername = опционально, если удалось вытащить из DOM @-handle\n  loginCheckedAt       DateTime?\n  loginCheckedStatus   Boolean?\n  loginCheckedUsername String?\n  // Прогрев аккаунта\n  warmupStatus         WarmupStatus             @default(new)\n  lastWarmupAt         DateTime?\n  totalPostsPublished  Int                      @default(0)\n  createdAt            DateTime                 @default(now())\n  updatedAt            DateTime                 @updatedAt\n  uploads              Upload[]\n  groups               AccountGroupMember[]\n  styleProfile         AccountStyleProfile?\n  deviceProfile        DeviceProfile?\n  postingJobs          PostingJob[]\n  warmupSessions       WarmupSession[]\n  deviceProfileLinks   DeviceProfileAccount[]\n  metricsSnapshots     AccountMetricsSnapshot[]\n  proxyDeepCheckLogs   ProxyDeepCheckLog[]\n\n  @@index([appId, status])\n  @@index([appId, platform, status])\n  @@index([proxyId])\n  @@index([warmupStatus])\n}\n\n// --- Apify Account Metrics (Часть C) ---\n//\n// Снимок метрик профиля соцсети, полученный через Apify profile-scrapers.\n// Идемпотентность 24h rolling — повторный fetch в течение суток возвращает\n// последний 'ok'-снимок без нового запроса к Apify (если не указан ?force=1).\n//\n// Денормализация appId сюда НЕ нужна: socialAccount.appId всегда достижим\n// одним join'ом, экономия одного поля важнее (snapshot копится много за месяцы).\n//\n// onDelete: Cascade — при удалении аккаунта снимки удаляются (бессмысленны без него).\nmodel AccountMetricsSnapshot {\n  id              String        @id @default(cuid())\n  socialAccountId Int\n  socialAccount   SocialAccount @relation(fields: [socialAccountId], references: [id], onDelete: Cascade)\n  fetchedAt       DateTime      @default(now())\n\n  // Core metrics — BigInt для случаев когда счётчик может превысить 2.1B\n  // (например, YouTube channel views у крупных каналов)\n  followers      BigInt?\n  following      BigInt?\n  totalViews     BigInt?\n  totalLikes     BigInt?\n  totalComments  BigInt?\n  postsCount     Int? // Миллиарды постов на один аккаунт нереалистичны\n  avgViewsPer30d BigInt?\n  engagementRate Float? // 0..1 из выборки последних N постов\n\n  // Profile metadata (snapshot для истории — bio/avatar могут меняться)\n  bio        String?\n  avatarUrl  String?\n  isVerified Boolean?\n\n  // Observability\n  status       String  @default(\"ok\") // 'ok' | 'error'\n  errorMessage String?\n  // { sampleSize: number, posts: NormalizedPost[], rawSample?: unknown }\n  rawData      Json?\n  // На будущее — привязка к pipeline run (когда появится metrics node)\n  agentRunId   Int?\n\n  @@unique([socialAccountId, fetchedAt])\n  @@index([socialAccountId, fetchedAt(sort: Desc)])\n  @@index([status])\n}\n\n// --- Прокси-инфраструктура (Social Automation iteration 1) ---\n\nmodel Proxy {\n  id                  String              @id @default(cuid())\n  label               String\n  provider            String? // 'iproyal' | 'proxyempire' | 'mobile_proxy_space' | 'other'\n  type                ProxyType\n  protocol            ProxyProtocol       @default(http)\n  // Зашифрованные credentials (AES-256-GCM)\n  host                String\n  port                Int\n  username            String?\n  password            String?\n  rotationUrl         String?\n  expectedCountry     String?\n  expectedCity        String?\n  ipv4Only            Boolean             @default(false)\n  status              ProxyStatus         @default(unverified)\n  lastCheckedAt       DateTime?\n  lastCheckResult     Json?\n  consecutiveFailures Int                 @default(0)\n  // Дедупликация Telegram-алёртов: { [reason]: { lastAt: ISO-string, count: number } }\n  // reasons: 'leak' | 'consecutive_failures_3' | 'auth_failed' | 'expired'\n  alertHistory        Json?\n  monthlyTrafficGB    Float?\n  expiresAt           DateTime?\n  createdById         Int\n  notes               String?\n  createdAt           DateTime            @default(now())\n  updatedAt           DateTime            @updatedAt\n  socialAccounts      SocialAccount[]\n  healthChecks        ProxyHealthCheck[]\n  deepCheckLogs       ProxyDeepCheckLog[]\n  deviceProfiles      DeviceProfile[]\n\n  @@index([status])\n  @@index([type, status])\n  @@index([createdById])\n}\n\n/**\n * Уровень C deep proxy check log.\n * Уровень A/B (быстрый probe.ts через Node http-agent) сохраняется в ProxyHealthCheck.\n * Уровень C (реальный Indigo browser + CDP + ifconfig.me inside Chromium) — здесь.\n * Гибридная схема: денормализованные ключевые поля (detectedIp/isLeaking/outcome/\n * proxyActuallyWorking/durationMs/recommendation) + fullResult JSON для drill-down.\n * Это даёт быстрый list/index без JSON parsing, при этом не теряет полную структуру\n * DeepProxyCheckResult.steps для отладки.\n * Уровни A/B и C НЕ shared в одну таблицу потому что:\n * - A/B частые/дешёвые (>100/день), C редкие/дорогие (<50/неделю)\n * - shape steps/verdict сильно различается\n * - JOIN history per proxy естественнее с раздельными таблицами\n * onDelete: Proxy=Cascade (логи бесполезны), SocialAccount/IndigoProfile/User=SetNull\n * (лог сохраняется для аналитики прокси).\n */\nmodel ProxyDeepCheckLog {\n  id      String @id @default(cuid())\n  proxyId String\n  proxy   Proxy  @relation(fields: [proxyId], references: [id], onDelete: Cascade)\n\n  /**\n   * Account c которого был запущен (null если прокси не привязан или account удалён).\n   */\n  socialAccountId Int?\n  socialAccount   SocialAccount? @relation(fields: [socialAccountId], references: [id], onDelete: SetNull)\n\n  /**\n   * Device profile использованный для проверки. Физическая колонка остаётся \"indigoProfileId\".\n   */\n  deviceProfileId String?        @map(\"indigoProfileId\")\n  deviceProfile   DeviceProfile? @relation(fields: [deviceProfileId], references: [id], onDelete: SetNull)\n\n  /**\n   * Кто инициировал. SetNull при deactivate user'а.\n   */\n  initiatedById Int?\n  initiatedBy   ZavodUser? @relation(\"ProxyDeepCheckLogInitiator\", fields: [initiatedById], references: [id], onDelete: SetNull)\n\n  /**\n   * 'manual' | 'scheduled' | 'account_check'. Резерв на будущее, в MVP только 'manual'.\n   */\n  triggeredFrom String @default(\"manual\")\n\n  /**\n   * 'ok' | 'leak' | 'error' | 'precondition_failed'.\n   */\n  outcome String\n\n  startedAt  DateTime  @default(now())\n  finishedAt DateTime?\n  durationMs Int?\n\n  /**\n   * Денормализованные ключевые поля (быстрый list view без JSON parsing).\n   */\n  detectedIp              String?\n  detectedCountry         String?\n  detectedCity            String?\n  isLeaking               Boolean?\n  matchesProxyExpectation Boolean?\n  /**\n   * false если упал на любом шаге (profileStart/cdpConnect/pageLoad/ipExtraction/profileStop).\n   */\n  proxyActuallyWorking    Boolean  @default(false)\n  /**\n   * Human-readable recommendation от verdict.recommendation.\n   */\n  recommendation          String?\n\n  /**\n   * Полная структура DeepProxyCheckResult для drill-down. См. shared/types/deep-proxy-check.ts.\n   */\n  fullResult Json?\n\n  createdAt DateTime @default(now())\n\n  @@index([proxyId, createdAt(sort: Desc)])\n  @@index([socialAccountId, createdAt(sort: Desc)])\n  @@index([outcome, createdAt(sort: Desc)])\n}\n\nmodel ProxyHealthCheck {\n  id              String   @id @default(cuid())\n  proxyId         String\n  proxy           Proxy    @relation(fields: [proxyId], references: [id], onDelete: Cascade)\n  checkedAt       DateTime @default(now())\n  triggeredBy     String // 'manual' | 'scheduled' | 'pre_session'\n  tcpConnectOk    Boolean\n  httpProbeOk     Boolean\n  detectedIp      String?\n  detectedCountry String?\n  detectedCity    String?\n  latencyMs       Int?\n  isLeaking       Boolean?\n  errorCategory   String? // 'timeout' | 'connection_refused' | 'auth_failed' | 'leak' | 'unknown'\n  errorMessage    String?\n  rawProbeData    Json?\n\n  @@index([proxyId, checkedAt(sort: Desc)])\n}\n\n// --- Device profiles (Social Automation iteration 2 → Этап 2 DuoPlus-нейтрализация) ---\n// Зеркало профилей устройства (Indigo legacy → DuoPlus Android cloud phone).\n// socialAccountId связывает 1:1 с SocialAccount, proxyId — с Proxy.\n// config: opaque snapshot полной схемы провайдера для стабильности при расширении.\n// Этап 2: Prisma-модель переименована (DeviceProfile), физ. таблица остаётся\n// \"IndigoProfile\" через @@map — rename без DDL, ноль риска для данных.\n// enum IndigoSyncStatus НЕ переименован (Prisma @@map не работает на enum →\n// был бы ALTER TYPE на проде). TS-alias DeviceSyncStatus добавлен в shared/коде\n// на Этапе 5. Физический rename enum — Этап 3.\n\nenum IndigoSyncStatus {\n  synced // в нашей БД и в Indigo\n  local_only // создан у нас, ещё не запушен в Indigo\n  remote_only // существует в Indigo но не привязан в нашей БД\n  conflict // изменения в обоих местах\n  deleted_remote // удалён в Indigo\n  error\n  archived // soft-delete оператором, sync пропускает, не показывается в UI\n}\n\nmodel DeviceProfile {\n  id                   String                 @id @default(cuid())\n  // External (provider side). NULL допустим для local_only до push в провайдер.\n  indigoId             String?                @unique\n  indigoFolderId       String?\n  // Linkage. socialAccountId — denormalized \"primary account\" указатель\n  // (после M.1 multi-account). Оставлен для backwards compat с 26 файлами\n  // сервера. Реальные привязки — через DeviceProfileAccount[].\n  socialAccountId      Int?                   @unique\n  socialAccount        SocialAccount?         @relation(fields: [socialAccountId], references: [id], onDelete: SetNull)\n  // Multi-account 1:N (Цикл M). isPrimary=true элемент = primary, его id\n  // зеркалится в socialAccountId выше через addAccount/removePrimary логику.\n  accounts             DeviceProfileAccount[]\n  proxyId              String?\n  proxy                Proxy?                 @relation(fields: [proxyId], references: [id], onDelete: SetNull)\n  // Configuration snapshot\n  name                 String\n  platformType         String                 @default(\"desktop\") // 'desktop' | 'mobile_android' | 'mobile_ios'\n  os                   String? // 'Windows 10' | 'macOS' | 'Android 13'\n  userAgent            String?\n  screenResolution     String? // '1920x1080' | '390x844'\n  language             String? // 'en-US'\n  timezone             String? // 'America/New_York'\n  // Полная конфигурация Indigo (fingerprint/parameters/storage/...) — opaque snapshot\n  config               Json?\n  // Status\n  syncStatus           IndigoSyncStatus       @default(local_only)\n  lastSyncedAt         DateTime?\n  lastSyncError        String?\n  // Sessions tracking\n  totalSessions        Int                    @default(0)\n  lastSessionStartedAt DateTime?\n  lastSessionEndedAt   DateTime?\n  lastSessionPort      Int?\n  // Metadata\n  notes                String?\n  tags                 String[]               @default([])\n  createdById          Int?\n  proxyDeepCheckLogs   ProxyDeepCheckLog[]\n  createdAt            DateTime               @default(now())\n  updatedAt            DateTime               @updatedAt\n\n  @@index([syncStatus])\n  @@index([socialAccountId])\n  @@index([proxyId])\n  // Физ. таблица остаётся \"IndigoProfile\" — rename без DDL (Этап 2).\n  @@map(\"IndigoProfile\")\n}\n\n// DeviceProfileAccount (Цикл M) — 1:1:1 связка между DeviceProfile, SocialAccount и Proxy.\n// @@unique([profileId]) — один профиль устройства = максимум один аккаунт (защита от\n// мульти-аккаунт конфигураций, ведущих к бану). isPrimary=true всегда (вырождается при 1:1),\n// дублируется в DeviceProfile.socialAccountId (denorm) для backwards compat.\n// addedAt/addedById — audit trail. Физ. таблица остаётся \"IndigoProfileAccount\" (@@map, без DDL).\nmodel DeviceProfileAccount {\n  id              String        @id @default(cuid())\n  profileId       String\n  profile         DeviceProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  socialAccountId Int\n  socialAccount   SocialAccount @relation(fields: [socialAccountId], references: [id], onDelete: Cascade)\n  isPrimary       Boolean       @default(true)\n  addedAt         DateTime      @default(now())\n  addedById       Int?\n\n  @@unique([profileId])\n  @@unique([profileId, socialAccountId])\n  @@index([socialAccountId])\n  @@index([profileId, isPrimary])\n  @@map(\"IndigoProfileAccount\")\n}\n\nmodel AccountGroup {\n  id           Int                  @id @default(autoincrement())\n  appId        Int\n  app          App                  @relation(fields: [appId], references: [id])\n  name         String\n  styleMode    String               @default(\"independent\") // independent | unified | base_with_overrides\n  stylePolicy  Json? // GroupStylePolicy\n  // Стратегия распределения публикаций по членам группы при upload-ноде\n  dispatchMode String               @default(\"round_robin\") // round_robin | all | first_active\n  createdAt    DateTime             @default(now())\n  updatedAt    DateTime             @updatedAt\n  members      AccountGroupMember[]\n  cycles       ProductionCycle[]\n  uploads      Upload[]\n\n  @@index([appId])\n}\n\n// --- Account Style Profile ---\n\nmodel AccountStyleProfile {\n  id              Int                    @id @default(autoincrement())\n  socialAccountId Int                    @unique\n  socialAccount   SocialAccount          @relation(fields: [socialAccountId], references: [id], onDelete: Cascade)\n  version         Int                    @default(1)\n  data            Json // AccountStyleProfileData\n  status          String                 @default(\"not_set\") // not_set | partial | complete\n  createdAt       DateTime               @default(now())\n  updatedAt       DateTime               @updatedAt\n  revisions       AccountStyleRevision[]\n\n  @@index([status])\n}\n\nmodel AccountStyleRevision {\n  id              Int                 @id @default(autoincrement())\n  profileId       Int\n  profile         AccountStyleProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  version         Int\n  changeType      String // manual | ai_suggestion | analytics_derived\n  changeSummary   String\n  changedSections String[]\n  previousData    Json // partial snapshot\n  newData         Json // partial snapshot\n  accepted        Boolean             @default(false)\n  appliedById     Int?\n  createdAt       DateTime            @default(now())\n\n  @@index([profileId, createdAt])\n}\n\nmodel AccountGroupMember {\n  id              Int           @id @default(autoincrement())\n  groupId         Int\n  group           AccountGroup  @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  socialAccountId Int\n  socialAccount   SocialAccount @relation(fields: [socialAccountId], references: [id], onDelete: Cascade)\n\n  @@unique([groupId, socialAccountId])\n}\n\nmodel Upload {\n  id              Int                   @id @default(autoincrement())\n  videoId         Int\n  video           Video                 @relation(fields: [videoId], references: [id])\n  socialAccountId Int\n  socialAccount   SocialAccount         @relation(fields: [socialAccountId], references: [id])\n  // Если Upload порождён выбором группы — здесь её id (для аналитики и трекинга стратегии)\n  accountGroupId  Int?\n  accountGroup    AccountGroup?         @relation(fields: [accountGroupId], references: [id], onDelete: SetNull)\n  // Снимок dispatchMode на момент создания Upload (round_robin | all | first_active)\n  dispatchMode    String?\n  applicationId   Int?\n  status          UploadStatus          @default(pending)\n  postStatus      PostStatus            @default(active)\n  publishMode     String                @default(\"immediate\")\n  scheduledAt     DateTime?\n  platformPostId  String?\n  platformPostUrl String?\n  title           String\n  description     String?\n  hashtags        String[]\n  idempotencyKey  String                @unique\n  errorMessage    String?\n  blockedByEnv    Boolean               @default(false)\n  attemptCount    Int                   @default(0)\n  lastAttemptAt   DateTime?\n  createdAt       DateTime              @default(now())\n  updatedAt       DateTime              @updatedAt\n  // --- Pipeline tracking (nullable, for standalone/pipeline separation) ---\n  runId           Int?\n  run             WorkflowRun?          @relation(fields: [runId], references: [id], onDelete: SetNull)\n  pipelineId      Int?\n  pipeline        Pipeline?             @relation(fields: [pipelineId], references: [id], onDelete: SetNull)\n  metrics         PostMetrics[]\n  references      Reference[]\n  attempts        SocialUploadAttempt[]\n  postingJob      PostingJob?\n\n  @@index([status])\n  @@index([videoId])\n  @@index([runId])\n  @@index([pipelineId])\n  @@index([accountGroupId])\n}\n\nmodel SocialUploadAttempt {\n  id               Int       @id @default(autoincrement())\n  uploadId         Int\n  upload           Upload    @relation(fields: [uploadId], references: [id], onDelete: Cascade)\n  attemptNumber    Int\n  status           String\n  requestSnapshot  Json?\n  responseSnapshot Json?\n  externalUploadId String?\n  externalPostId   String?\n  startedAt        DateTime  @default(now())\n  finishedAt       DateTime?\n  errorMessage     String?\n  createdAt        DateTime  @default(now())\n\n  @@index([uploadId, attemptNumber])\n}\n\nmodel PostMetrics {\n  id           Int      @id @default(autoincrement())\n  uploadId     Int\n  upload       Upload   @relation(fields: [uploadId], references: [id], onDelete: Cascade)\n  views        Int      @default(0)\n  likes        Int      @default(0)\n  comments     Int      @default(0)\n  shares       Int      @default(0)\n  watchThrough Float    @default(0)\n  ctr          Float    @default(0)\n  followerGain Int      @default(0)\n  collectedAt  DateTime @default(now())\n\n  @@index([uploadId, collectedAt])\n}\n\nmodel Reference {\n  id         Int      @id @default(autoincrement())\n  uploadId   Int\n  upload     Upload   @relation(fields: [uploadId], references: [id], onDelete: Cascade)\n  reason     String\n  aiAnalysis String?\n  addedAt    DateTime @default(now())\n\n  @@unique([uploadId])\n}\n\nmodel ProductionCycle {\n  id           Int           @id @default(autoincrement())\n  appId        Int\n  app          App           @relation(fields: [appId], references: [id])\n  groupId      Int?\n  accountGroup AccountGroup? @relation(fields: [groupId], references: [id])\n  status       CycleStatus   @default(pending)\n  startedById  Int\n  startedAt    DateTime      @default(now())\n  completedAt  DateTime?\n  errorMessage String?\n  trendsFound  Int           @default(0)\n  scenariosGen Int           @default(0)\n  videosGen    Int           @default(0)\n  uploadsCount Int           @default(0)\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n  logs         AgentLog[]\n}\n\nmodel AgentLog {\n  id        Int              @id @default(autoincrement())\n  cycleId   Int?\n  cycle     ProductionCycle? @relation(fields: [cycleId], references: [id], onDelete: SetNull)\n  module    String\n  level     AgentLogLevel    @default(info)\n  message   String\n  details   Json?\n  resolved  Boolean          @default(false)\n  createdAt DateTime         @default(now())\n\n  @@index([module, createdAt])\n  @@index([level, createdAt])\n}\n\n// --- Audit-log расшифровки секретов (Social Automation iteration 1) ---\n// Append-only, не редактируется. Запись создаётся ДО расшифровки в readSecret().\n\nmodel SecretAccessLog {\n  id         String    @id @default(cuid())\n  userId     Int\n  user       ZavodUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n  entityType String // 'SocialAccount.password' | 'Proxy.password' | 'SocialAccount.twoFASecret' | etc.\n  entityId   String // string for cuid (Proxy) or stringified int (SocialAccount)\n  action     String // 'view' | 'use_in_session' | 'export'\n  clientIp   String?\n  userAgent  String?\n  reason     String?\n  createdAt  DateTime  @default(now())\n\n  @@index([entityType, entityId, createdAt(sort: Desc)])\n  @@index([userId, createdAt(sort: Desc)])\n}\n\nmodel TelegramChat {\n  id            Int      @id @default(autoincrement())\n  chatId        String   @unique\n  userId        Int?\n  chatType      String   @default(\"private\") // private, group, supergroup, channel\n  title         String?\n  username      String?\n  alertsEnabled Boolean  @default(true)\n  isAuthorized  Boolean  @default(false)\n  routingTags   String[] // event types this chat subscribes to: cycle_started, upload_success, critical_error, idea_created\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  deliveries    TelegramDelivery[]\n  commandAudits TelegramCommandAudit[]\n}\n\nenum TelegramDeliveryStatus {\n  pending\n  sent\n  failed\n}\n\nmodel TelegramMessageTemplate {\n  id              Int      @id @default(autoincrement())\n  key             String   @unique\n  title           String\n  category        String   @default(\"alert\") // alert, notification, report, custom\n  messageBody     String\n  variablesSchema Json? // { \"cycleName\": \"string\", \"errorMessage\": \"string\" }\n  isActive        Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  deliveries TelegramDelivery[]\n}\n\nmodel TelegramDelivery {\n  id                Int                      @id @default(autoincrement())\n  templateId        Int?\n  template          TelegramMessageTemplate? @relation(fields: [templateId], references: [id], onDelete: SetNull)\n  eventType         String // cycle_started, upload_success, critical_error, test, custom, idea_created\n  relatedEntityType String? // cycle, upload, idea, scenario\n  relatedEntityId   Int?\n  targetChatId      String\n  chat              TelegramChat?            @relation(fields: [targetChatId], references: [chatId])\n  status            TelegramDeliveryStatus   @default(pending)\n  telegramMessageId Int? // Telegram's message_id for editing\n  errorMessage      String?\n  messageText       String? // snapshot of sent text\n  sentAt            DateTime?\n  createdAt         DateTime                 @default(now())\n\n  @@index([eventType, createdAt])\n  @@index([targetChatId, createdAt])\n  @@index([status])\n}\n\nmodel TelegramCommandAudit {\n  id                Int           @id @default(autoincrement())\n  chatId            String\n  chat              TelegramChat? @relation(fields: [chatId], references: [chatId])\n  telegramUserId    String?\n  telegramUsername  String?\n  command           String\n  parsedArgs        String?\n  resultStatus      String        @default(\"success\") // success, error, unauthorized, not_found\n  relatedEntityType String?\n  relatedEntityId   Int?\n  errorMessage      String?\n  createdAt         DateTime      @default(now())\n\n  @@index([chatId, createdAt])\n  @@index([command, createdAt])\n}\n\nmodel TelegramApiKey {\n  id         Int       @id @default(autoincrement())\n  key        String    @unique // tgk_... random token\n  label      String // human-readable purpose\n  isActive   Boolean   @default(true)\n  createdAt  DateTime  @default(now())\n  lastUsedAt DateTime?\n  expiresAt  DateTime?\n}\n\nenum PipelineStatus {\n  active\n  inactive\n}\n\nenum RunStatus {\n  pending\n  running\n  success\n  failed\n  cancelled\n  no_data\n}\n\nenum StepStatus {\n  pending\n  running\n  success\n  partial\n  no_data\n  failed\n  skipped\n  cancelled\n  blocked\n  waiting\n}\n\nenum TriggerType {\n  manual\n  schedule\n  webhook\n}\n\nmodel PipelineTag {\n  id        Int        @id @default(autoincrement())\n  name      String     @unique\n  createdAt DateTime   @default(now())\n  pipelines Pipeline[]\n}\n\nmodel Pipeline {\n  id                  Int               @id @default(autoincrement())\n  userId              Int\n  name                String\n  description         String?\n  markdownDescription String?\n  icon                String?\n  color               String?\n  tags                PipelineTag[]\n  status              PipelineStatus    @default(inactive)\n  graphData           Json              @default(\"{\\\"nodes\\\":[],\\\"edges\\\":[]}\")\n  sharedWith          Int[]\n  webhookToken        String?           @unique\n  webhookSecret       String?\n  webhookEnabled      Boolean           @default(true)\n  activeVersionId     Int?\n  // Единый стиль субтитров для всего контейнера (один аккаунт = один visual brand).\n  // Генерируется один раз при первой генерации сценария, переиспользуется во всех\n  // последующих видео pipeline. SubtitleStyleProfile JSON, валидированный по\n  // контрасту/размеру через render.ts:clampForReadability.\n  subtitleStyle       Json?\n  createdAt           DateTime          @default(now())\n  updatedAt           DateTime          @updatedAt\n  lastEditedAt        DateTime          @default(now())\n  runs                WorkflowRun[]\n  versions            PipelineVersion[]\n  schedule            PipelineSchedule?\n  webhookLogs         WebhookLog[]\n  // --- Back-refs for entities created within this pipeline (nullable FK on child) ---\n  scenarios           Scenario[]\n  trends              Trend[]\n  videos              Video[]\n  uploads             Upload[]\n  ideas               Idea[]\n  postingJobs         PostingJob[]\n}\n\nmodel WorkflowRun {\n  id                Int            @id @default(autoincrement())\n  pipelineId        Int\n  pipeline          Pipeline       @relation(fields: [pipelineId], references: [id], onDelete: Cascade)\n  status            RunStatus      @default(pending)\n  triggerType       TriggerType    @default(manual)\n  triggeredBy       Int?\n  graphSnapshot     Json?\n  graphVersionId    Int?\n  retryOfRunId      Int?\n  replayOfRunId     Int?\n  parentRunId       Int?\n  cancelRequestedAt DateTime?\n  cancelRequestedBy Int?\n  errorMessage      String?\n  errorCategory     String?\n  startedAt         DateTime       @default(now())\n  finishedAt        DateTime?\n  createdAt         DateTime       @default(now())\n  steps             WorkflowStep[]\n  // --- Back-refs for entities created within this run (nullable FK on child) ---\n  scenarios         Scenario[]\n  trends            Trend[]\n  videos            Video[]\n  uploads           Upload[]\n  ideas             Idea[]\n  postingJobs       PostingJob[]\n\n  @@index([pipelineId, createdAt])\n  @@index([status])\n  @@index([parentRunId])\n}\n\nmodel WorkflowStep {\n  id            Int         @id @default(autoincrement())\n  runId         Int\n  run           WorkflowRun @relation(fields: [runId], references: [id], onDelete: Cascade)\n  nodeId        String\n  nodeName      String\n  nodeType      String\n  status        StepStatus  @default(pending)\n  input         Json?\n  output        Json?\n  error         String?\n  errorCategory String?\n  logs          Json?\n  attemptCount  Int         @default(0)\n  retryPolicy   Json?\n  artifacts     Json?\n  startedAt     DateTime?\n  finishedAt    DateTime?\n  duration      Int?\n  createdAt     DateTime    @default(now())\n\n  @@index([runId, nodeId])\n}\n\nmodel PipelineVersion {\n  id          Int      @id @default(autoincrement())\n  pipelineId  Int\n  pipeline    Pipeline @relation(fields: [pipelineId], references: [id], onDelete: Cascade)\n  version     Int\n  graphData   Json\n  name        String?\n  description String?\n  createdById Int?\n  isDeployed  Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@unique([pipelineId, version])\n}\n\nenum IdeaSource {\n  manual\n  telegram\n  pipeline\n  marketingcamp\n}\n\nenum SyncStatus {\n  none\n  synced\n  pending_export\n  pending_import\n  conflict\n  error\n}\n\nenum SyncDirection {\n  local\n  imported\n  exported\n  bidirectional\n}\n\nenum IdeaStatus {\n  pending\n  processing\n  ready\n  in_work\n  completed\n  failed\n}\n\nenum IdeaActionType {\n  create\n  edit\n  delete\n  restore\n  reanalyze\n  send_to_scenario\n}\n\nmodel Idea {\n  id               Int                  @id @default(autoincrement())\n  appId            Int?\n  app              App?                 @relation(fields: [appId], references: [id])\n  source           IdeaSource           @default(manual)\n  sourceUrl        String?\n  platform         Platform?\n  transcription    String?\n  language         String?\n  title            String?\n  hook             String?\n  body             String?\n  cta              String?\n  visualStyle      String?\n  whyViral         String?\n  status           IdeaStatus           @default(pending)\n  analysisStatus   AnalysisStatus       @default(none)\n  operatorNotes    String?\n  tags             String[]\n  isDeleted        Boolean              @default(false)\n  deletedAt        DateTime?\n  sentToScenarioAt DateTime?\n  createdById      Int?\n  errorMessage     String?\n  // --- Reference fields ---\n  mediaType        String? // video | image | unknown\n  thumbnailUrl     String? // extracted or provided thumbnail\n  referenceStatus  String? // none | pending | running | completed | failed\n  analysisProgress String? // JSON ReferenceProgress, null когда не идёт анализ\n  // --- MarketingCamp sync fields ---\n  externalId       Int?                 @unique // ID креатива в MarketingCamp\n  syncStatus       SyncStatus           @default(none)\n  syncDirection    SyncDirection        @default(local)\n  lastSyncedAt     DateTime?\n  lastSyncError    String?\n  remoteSnapshot   Json? // raw payload snapshot с MarketingCamp\n  localDirty       Boolean              @default(false) // локальные изменения после sync\n  createdAt        DateTime             @default(now())\n  updatedAt        DateTime             @updatedAt\n  // --- Pipeline tracking (nullable, for standalone/pipeline separation) ---\n  runId            Int?\n  run              WorkflowRun?         @relation(fields: [runId], references: [id], onDelete: SetNull)\n  pipelineId       Int?\n  pipeline         Pipeline?            @relation(fields: [pipelineId], references: [id], onDelete: SetNull)\n  analysis         IdeaAnalysis?\n  operatorActions  IdeaOperatorAction[]\n\n  @@index([isDeleted, status])\n  @@index([sourceUrl])\n  @@index([externalId])\n  @@index([syncStatus])\n  @@index([runId])\n  @@index([pipelineId])\n}\n\nmodel IdeaAnalysis {\n  id                 Int      @id @default(autoincrement())\n  ideaId             Int      @unique\n  idea               Idea     @relation(fields: [ideaId], references: [id], onDelete: Cascade)\n  hookAnalysis       Json\n  sceneStructure     Json\n  visualStyle        Json\n  viralityReasons    Json\n  summary            String\n  modelVersion       String\n  promptVersion      String\n  confidence         Float?\n  // --- Reference analysis extension ---\n  referenceBreakdown Json? // ReferenceBreakdown: transcript, scenes, patterns, anti-copy\n  referenceVersion   String? // version of reference analyzer\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n}\n\nmodel IdeaOperatorAction {\n  id         Int            @id @default(autoincrement())\n  ideaId     Int\n  idea       Idea           @relation(fields: [ideaId], references: [id], onDelete: Cascade)\n  actionType IdeaActionType\n  reason     String?\n  actorId    Int?\n  createdAt  DateTime       @default(now())\n\n  @@index([ideaId, createdAt])\n}\n\nmodel TrendwatcherProfile {\n  id                  Int               @id @default(autoincrement())\n  appId               Int\n  app                 App               @relation(fields: [appId], references: [id])\n  name                String\n  actorId             String            @default(\"clockworks/tiktok-scraper\")\n  keywords            String[]\n  platforms           Platform[]\n  language            String?\n  geo                 String?\n  viewCountMin        Int?\n  viewCountMax        Int?\n  maxItems            Int               @default(20)\n  enabled             Boolean           @default(true)\n  scheduleEnabled     Boolean           @default(false)\n  scheduleCron        String?\n  scheduleTimezone    String            @default(\"UTC\")\n  scheduleNextRunAt   DateTime?\n  scheduleLastRunAt   DateTime?\n  lastRunId           Int?\n  lastSuccessfulRunAt DateTime?\n  validationStatus    String? // valid, token_missing, token_invalid_or_forbidden, actor_not_found, profile_invalid, paid_apis_disabled, network_error\n  validationSummary   String? // Human-readable summary of last validation\n  validatedAt         DateTime? // When the profile was last validated\n  isInline            Boolean           @default(false) // true = создан из pipeline inline mode, скрыт из standalone UI\n  sourceNodeId        String? // canvas id ноды pipeline, из которой создан inline профиль\n  sourcePipelineId    Int? // id pipeline, из которого создан inline профиль\n  createdAt           DateTime          @default(now())\n  updatedAt           DateTime          @updatedAt\n  runs                TrendwatcherRun[]\n\n  @@index([isInline])\n  @@index([appId, isInline])\n}\n\nenum TrendwatcherRunStatus {\n  pending\n  starting\n  running\n  importing\n  analyzing\n  completed\n  failed\n  canceled\n  partially_completed\n}\n\nenum TrendwatcherTriggerType {\n  manual\n  scheduled\n  pipeline\n}\n\nmodel TrendwatcherRun {\n  id                 Int                     @id @default(autoincrement())\n  profileId          Int\n  profile            TrendwatcherProfile     @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  status             TrendwatcherRunStatus   @default(pending)\n  triggerType        TrendwatcherTriggerType @default(manual)\n  externalRunId      String?\n  sourceType         String?\n  startedAt          DateTime                @default(now())\n  completedAt        DateTime?\n  canceledAt         DateTime?\n  failureReason      String?\n  errorCategory      String? // profile_validation_error, apify_start_failed, apify_run_failed, apify_timeout, dataset_empty, import_failed, import_partial_failure, canceled, watchdog_failed, unknown_external_error\n  errorStep          String? // init, starting, running, importing, canceled, unknown\n  errorSummary       String? // Human-readable short summary for operator\n  apifyStatus        String? // Raw Apify run status: SUCCEEDED, FAILED, ABORTED, TIMED-OUT, etc.\n  apifyStatusMessage String? // statusMessage from Apify run response\n  canRetry           Boolean                 @default(false)\n  needsProfileFix    Boolean                 @default(false)\n  datasetId          String?\n  foundCount         Int                     @default(0)\n  importedCount      Int                     @default(0)\n  analyzedCount      Int                     @default(0)\n  skippedCount       Int                     @default(0)\n  dedupSkipCount     Int                     @default(0)\n  viewCountSkipCount Int                     @default(0)\n  warningCount       Int                     @default(0)\n  initiatedBy        String?\n  createdAt          DateTime                @default(now())\n  updatedAt          DateTime                @updatedAt\n  logs               TrendwatcherRunLog[]\n\n  @@index([profileId, status])\n  @@index([status])\n  @@index([startedAt])\n}\n\nmodel TrendwatcherRunLog {\n  id        Int             @id @default(autoincrement())\n  runId     Int\n  run       TrendwatcherRun @relation(fields: [runId], references: [id], onDelete: Cascade)\n  level     AgentLogLevel   @default(info)\n  message   String\n  step      String?\n  payload   Json?\n  createdAt DateTime        @default(now())\n\n  @@index([runId, createdAt])\n}\n\nmodel PipelineSchedule {\n  id             Int       @id @default(autoincrement())\n  pipelineId     Int       @unique\n  pipeline       Pipeline  @relation(fields: [pipelineId], references: [id], onDelete: Cascade)\n  cronExpr       String\n  timezone       String    @default(\"UTC\")\n  enabled        Boolean   @default(true)\n  lastRunAt      DateTime?\n  nextRunAt      DateTime?\n  lastRunStatus  String?\n  missedRunCount Int       @default(0)\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n}\n\nmodel WebhookLog {\n  id         Int      @id @default(autoincrement())\n  pipelineId Int\n  pipeline   Pipeline @relation(fields: [pipelineId], references: [id], onDelete: Cascade)\n  runId      Int?\n  sourceIp   String?\n  userAgent  String?\n  payload    Json?\n  statusCode Int      @default(200)\n  errorMsg   String?\n  createdAt  DateTime @default(now())\n\n  @@index([pipelineId, createdAt])\n}\n\nenum CredentialType {\n  api_key\n  bearer_token\n  basic_auth\n  oauth2\n  custom\n}\n\nmodel PipelineCredential {\n  id             Int            @id @default(autoincrement())\n  userId         Int\n  name           String\n  type           CredentialType @default(api_key)\n  encryptedData  String\n  metadata       Json?\n  description    String?\n  expiresAt      DateTime?\n  lastUsedAt     DateTime?\n  lastTestedAt   DateTime?\n  lastTestStatus String?\n  revokedAt      DateTime?\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @updatedAt\n  driveFiles     DriveFile[]\n  videoUploads   Video[]        @relation(\"VideoDriveCredential\")\n\n  @@unique([userId, name])\n  @@index([userId])\n}\n\nenum DriveSyncStatus {\n  detected\n  downloading\n  downloaded\n  imported_to_video\n  failed\n}\n\nmodel DriveFile {\n  id                  Int                @id @default(autoincrement())\n  userId              Int\n  user                ZavodUser          @relation(\"DriveFilesOwner\", fields: [userId], references: [id], onDelete: Cascade)\n  credentialId        Int\n  credential          PipelineCredential @relation(fields: [credentialId], references: [id], onDelete: Cascade)\n  driveFileId         String\n  name                String\n  mimeType            String\n  sizeBytes           BigInt?\n  driveCreatedAt      DateTime?\n  driveModifiedAt     DateTime?\n  driveUrl            String?\n  thumbnailUrl        String?\n  videoId             Int?               @unique\n  video               Video?             @relation(\"DriveFileVideo\", fields: [videoId], references: [id], onDelete: SetNull)\n  syncStatus          DriveSyncStatus    @default(detected)\n  localPath           String?\n  lastSyncedAt        DateTime?\n  syncError           String?\n  hasGeneratedCaption Boolean            @default(false)\n  createdAt           DateTime           @default(now())\n\n  @@unique([credentialId, driveFileId])\n  @@index([syncStatus])\n  @@index([hasGeneratedCaption])\n  @@index([userId])\n  @@index([videoId])\n}\n\nenum TaxonomyType {\n  strategy\n  hook_style\n  prompt_pattern\n  pipeline_category\n  kling_pattern\n}\n\nmodel TaxonomyItem {\n  id               Int          @id @default(autoincrement())\n  type             TaxonomyType\n  slug             String\n  name             String\n  shortDescription String\n  fullExplanation  String?\n  category         String?\n  tags             String[]\n  examples         String[]\n  useCases         String[]\n  isSystem         Boolean      @default(false)\n  isArchived       Boolean      @default(false)\n  createdById      Int?\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  @@unique([type, slug])\n  @@index([type, isArchived])\n  @@index([category])\n}\n\n/// AI Audit Trail — журнал всех AI-предложений и действий пользователя\nmodel AiAuditLog {\n  id             Int      @id @default(autoincrement())\n  /// Кто вызвал (userId). NULL для background pipeline calls (balance_v2 cost ledger).\n  userId         Int?\n  /// Тип операции: block_suggest | field_suggest | taxonomy_suggest | external_api_call\n  action         String\n  /// Тип ноды (для block/field suggest)\n  nodeType       String?\n  /// ID конвейера, в котором произведено действие\n  pipelineId     Int?\n  /// ID ноды на canvas (строковый, например \"trendwatcher-1712345-1\")\n  nodeCanvasId   String?\n  /// Какая модель была использована\n  model          String\n  /// Промт пользователя. NULL для не-suggest записей (external_api_call).\n  prompt         String?\n  /// Что AI предложил (JSON)\n  suggestions    Json?\n  /// Какие поля заблокированы (JSON)\n  blockedFields  Json?\n  /// Какие поля отклонены валидацией (JSON)\n  rejectedFields Json?\n  /// Что пользователь применил (JSON, заполняется при apply)\n  appliedFields  Json?\n  /// Статус: suggested | applied | partial | dismissed\n  status         String   @default(\"suggested\")\n  /// Оценка стоимости вызова в USD (по pricing table). NULL для старых записей или мок-режима.\n  costUsd        Decimal? @db.Decimal(10, 6)\n  /// Денормализованный service tag (balance_v2): anthropic | fal.ai | mubert | ...\n  service        String?\n  /// Cross-link с pipeline-видео (balance_v2)\n  videoId        Int?\n  /// stepKey (TEXT, чтобы не зависеть от VideoStepKey enum)\n  stepKey        String?\n  createdAt      DateTime @default(now())\n\n  @@index([userId])\n  @@index([action])\n  @@index([pipelineId])\n  @@index([createdAt])\n  @@index([service, createdAt])\n  @@index([videoId])\n}\n\n/// Manual balance entries для AI/proxy/music сервисов.\n/// Админ обновляет вручную с dashboard сервиса — бот показывает по /balance.\nmodel ServiceBalanceEntry {\n  id        Int      @id @default(autoincrement())\n  /// Идентификатор сервиса: fal.ai | anthropic | indigo | nodemaven | mubert\n  service   String   @unique\n  amount    Decimal  @db.Decimal(10, 2)\n  currency  String   @default(\"USD\")\n  /// Доп. данные (traffic_left_gb, days_remaining, и т.п.) — Json\n  metadata  Json?\n  /// Кто ввёл значение (userId)\n  enteredBy Int?\n  enteredAt DateTime @default(now()) @updatedAt\n  notes     String?\n\n  @@index([service])\n  @@index([enteredAt])\n}\n\n// --- Story-driven scenario models ---\n\nmodel ScenarioGenerationProfile {\n  id          Int        @id @default(autoincrement())\n  name        String\n  description String?\n  appId       Int?\n  app         App?       @relation(fields: [appId], references: [id], onDelete: SetNull)\n  isDefault   Boolean    @default(false)\n  settings    Json // ScenarioGenerationProfileData\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n  scenarios   Scenario[]\n\n  @@index([appId])\n}\n\nmodel ScenarioFeedback {\n  id           Int       @id @default(autoincrement())\n  scenarioId   Int?\n  scenario     Scenario? @relation(fields: [scenarioId], references: [id], onDelete: SetNull)\n  videoId      Int?\n  uploadId     Int?\n  feedbackText String\n  sentiment    String? // positive | negative | neutral | mixed\n  derived      Json? // ScenarioFeedbackDerived\n  source       String    @default(\"operator\") // operator | analytics | review\n  createdAt    DateTime  @default(now())\n\n  @@index([scenarioId])\n  @@index([videoId])\n  @@index([uploadId])\n}\n\nmodel ScenarioMemory {\n  id        Int      @id @default(autoincrement())\n  appId     Int?\n  app       App?     @relation(fields: [appId], references: [id], onDelete: SetNull)\n  scope     String   @default(\"global\") // global | app | trend\n  scopeId   Int? // trendId if scope=trend\n  data      Json // OptimizationMemoryData\n  version   Int      @default(1)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([appId, scope, scopeId])\n  @@index([scope])\n}\n\n// --- Critic Review — журнал AI-критика, сравнивающего N вариантов сценария ---\n//\n// Один CriticReview = один проход критика (одна итерация). При rework-цикле\n// пишется несколько записей с возрастающим iteration. fullReport хранит\n// CriticOutput целиком (массив scores, bestVariant, reasoning) — для UI\n// детального отчёта без повторных AI-вызовов.\nmodel CriticReview {\n  id               Int      @id @default(autoincrement())\n  scenarioId       Int\n  scenario         Scenario @relation(fields: [scenarioId], references: [id], onDelete: Cascade)\n  iteration        Int\n  variantsReviewed Int\n  bestVariantId    Int?\n  averageScore     Float\n  needsRework      Boolean\n  reachedThreshold Boolean\n  fullReport       Json\n  modelVersion     String\n  promptVersion    String\n  durationMs       Int\n  costEstimate     Float?\n  createdAt        DateTime @default(now())\n\n  // Атомарная защита от race condition: только 1 review per (scenarioId, iteration).\n  // Параллельные вызовы critic'а на одном scenarioId с одной iteration получат P2002 и gracefully break.\n  @@unique([scenarioId, iteration])\n  @@index([scenarioId, iteration])\n  @@index([scenarioId, createdAt])\n}\n\n// --- Favorite prompts — библиотека \"лучших практик\" на уровне per-scene промтов ---\n//\n// Маркетолог отмечает удачный VideoAsset.prompt звездой → фиксируется snapshot в promptText.\n// При генерации сценария story-architect получает до 5 таких промтов как ОРИЕНТИР (не копия).\n// appId=null — универсальный промт, виден всем приложениям.\n// sourceVideoAssetId с onDelete:SetNull — при удалении исходного ассета snapshot остаётся.\nmodel FavoritePrompt {\n  id                 Int         @id @default(autoincrement())\n  userId             Int\n  user               ZavodUser   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  appId              Int?\n  app                App?        @relation(fields: [appId], references: [id], onDelete: SetNull)\n  promptText         String // immutable snapshot из VideoAsset.prompt\n  sourceVideoAssetId Int?\n  sourceVideoAsset   VideoAsset? @relation(fields: [sourceVideoAssetId], references: [id], onDelete: SetNull)\n  tags               String[]\n  notes              String?\n  isPublic           Boolean     @default(true)\n  usageCount         Int         @default(0)\n  lastUsedAt         DateTime?\n  // AI structural pattern analysis (KlingPromptPattern: camera/lighting/actionStructure/mood/motionIntensity)\n  // Кешируется фоновым агентом prompt-pattern-extractor; пересчитывается только при ручном rerun.\n  aiPatternAnalysis  Json?\n  aiAnalyzedAt       DateTime?\n  aiAnalysisError    String?\n  aiAnalysisAttempts Int         @default(0)\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n\n  @@index([userId])\n  @@index([appId])\n  @@index([isPublic, appId])\n  @@index([tags], type: Gin)\n}\n\n// --- Posting jobs state machine (Social Automation iteration 4 prep) ---\n// Independent от Upload: Upload = OAuth API uploads (existing), PostingJob =\n// автоматический постинг через Indigo+Playwright. Параллельные системы.\n\nenum PostingJobStatus {\n  scheduled\n  queued\n  preparing\n  uploading\n  published\n  failed\n  retry_queued\n  cancelled\n}\n\nenum PostingErrorCategory {\n  auth_failed\n  proxy_dead\n  network_error\n  platform_5xx\n  platform_validation\n  platform_rate_limit\n  content_rejected\n  account_locked\n  internal_error\n  unknown\n  // --- Part D: browser automation specific categories ---\n  // login_required        — checkPlatformLoginStatus вернул loggedIn=false.\n  //                         Не retryable — оператор должен залогиниться через Indigo X desktop.\n  // browser_connect_failed — puppeteer.connect упал (automation off / port не открыт).\n  //                          Не retryable — нужно фиксить Indigo profile настройки.\n  // selector_not_found    — DOM не найден ни одним из fallback селекторов.\n  //                          Не retryable — TikTok/YT обновили вёрстку, нужно обновить poster.\n  // upload_failed         — page.setInputFiles или processing indicator не дождались.\n  //                          Retryable 1 раз (timeout на стороне платформы).\n  login_required\n  browser_connect_failed\n  selector_not_found\n  upload_failed\n}\n\nmodel PostingJob {\n  id              String        @id @default(cuid())\n  videoId         Int\n  video           Video         @relation(fields: [videoId], references: [id], onDelete: Cascade)\n  socialAccountId Int\n  socialAccount   SocialAccount @relation(fields: [socialAccountId], references: [id], onDelete: Cascade)\n  uploadId        Int?          @unique\n  upload          Upload?       @relation(fields: [uploadId], references: [id], onDelete: SetNull)\n  runId           Int?\n  run             WorkflowRun?  @relation(fields: [runId], references: [id], onDelete: SetNull)\n  pipelineId      Int?\n  pipeline        Pipeline?     @relation(fields: [pipelineId], references: [id], onDelete: SetNull)\n\n  status          PostingJobStatus @default(queued)\n  scheduledAt     DateTime?\n  // sha256(`videoId:socialAccountId:scheduledAtISO|asap`).slice(0, 32)\n  idempotencyKey  String           @unique\n  // Snapshot контента на момент создания job (title/description/hashtags/...).\n  // Не редактируется после создания — гарантирует идемпотентность retries.\n  contentSnapshot Json\n  platform        Platform\n\n  attemptCount Int       @default(0)\n  maxAttempts  Int       @default(3)\n  startedAt    DateTime?\n  finishedAt   DateTime?\n  durationMs   Int?\n\n  // Результат публикации\n  platformPostId  String?\n  platformPostUrl String?\n  // Платформа выдала warning о modified content / API made changes\n  apiMadeWarning  Boolean @default(false)\n\n  // Ошибка последней попытки\n  lastError              String?\n  errorCategory          PostingErrorCategory?\n  retryAt                DateTime?\n  // --- Part D: диагностика browser automation ---\n  // lastErrorPhase = одна из PostingPhase (\"session_start\" | \"cdp_connect\" | \"login_check\" | ...).\n  //                  Используется AccountDiagnosticPanel для понимания где упал runner.\n  // lastErrorScreenshotKey = storageKey скриншота с момента ошибки (zavodcamp/posting-errors/...).\n  //                          UI выдаёт через signed URL.\n  lastErrorPhase         String?\n  lastErrorScreenshotKey String?\n\n  // --- Phase-level FSM (PR1, аддитивно, nullable) ---\n  // Persisted runtime-состояние phase-level FSM YouTube-постинга:\n  // { fsmVersion, buildMarker, currentPhase, progress, draftVideoId,\n  //   phaseAttempts, classWindows, lastTransitionAt }.\n  // Форма: shared/types/youtube-posting-fsm.ts:YouTubePostingStateData.\n  // null / отсутствие fsmVersion = job НЕ управляется FSM (legacy-путь) — критично\n  // для backward-compat. На момент PR1 НИКТО не пишет в это поле (no-op foundation).\n  stateData Json?\n\n  createdById   Int?\n  createdBy     ZavodUser? @relation(\"PostingJobCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  cancelledById Int?\n  cancelledBy   ZavodUser? @relation(\"PostingJobCancelledBy\", fields: [cancelledById], references: [id], onDelete: SetNull)\n  cancelledAt   DateTime?\n  cancelReason  String?\n\n  logs PostingJobLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, scheduledAt])\n  @@index([status, retryAt])\n  @@index([socialAccountId, createdAt(sort: Desc)])\n  @@index([videoId])\n  @@index([runId, pipelineId])\n  @@index([retryAt])\n}\n\nmodel PostingJobLog {\n  id        String     @id @default(cuid())\n  jobId     String\n  job       PostingJob @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  level     String // 'info' | 'warn' | 'error'\n  message   String\n  data      Json?\n  createdAt DateTime   @default(now())\n\n  @@index([jobId, createdAt(sort: Desc)])\n}\n\n// --- Account Warming Planner (Social Automation iteration 4 — Track E) ---\n// Детерминистические ежедневные сессии прогрева для социальных аккаунтов.\n// Plan генерируется по seedable RNG (seed = accountId:dayKey), Runner — не в этом треке.\n\nmodel WarmupSession {\n  id              String              @id @default(cuid())\n  socialAccountId Int\n  socialAccount   SocialAccount       @relation(fields: [socialAccountId], references: [id], onDelete: Cascade)\n  status          WarmupSessionStatus @default(planned)\n  scheduledAt     DateTime\n  // Формат YYYY-MM-DD UTC. Используется для дедупликации planned/running на дату.\n  dayKey          String\n  // Seed формата 'accId:YYYY-MM-DD' — гарантирует детерминированность плана.\n  seed            String\n  // Один из 'new' | 'warming' | 'mature' (классификация на момент генерации).\n  ageBucket       String\n  // WarmupPlan structured (см. shared/types/warmup.ts).\n  plan            Json\n  // WarmupExecutionLog[] (заполнит runner в итерации 4).\n  executedActions Json?\n  startedAt       DateTime?\n  finishedAt      DateTime?\n  errorMessage    String?\n  createdById     Int?\n  createdAt       DateTime            @default(now())\n  updatedAt       DateTime            @updatedAt\n\n  @@index([socialAccountId, dayKey])\n  @@index([socialAccountId, scheduledAt])\n  @@index([status, scheduledAt])\n}\n\nmodel WarmupKeywordPool {\n  id          String    @id @default(cuid())\n  name        String\n  appId       Int?\n  app         App?      @relation(fields: [appId], references: [id], onDelete: SetNull)\n  // 'ru' | 'en' | null — null = универсальный.\n  language    String?\n  // 'general' | 'tech' | 'lifestyle' | 'fitness' | 'education' | 'music' | ...\n  category    String\n  // Опционально — привязка к платформе (если null, применяется ко всем).\n  platform    Platform?\n  keywords    String[]\n  hashtags    String[]  @default([])\n  isActive    Boolean   @default(true)\n  createdById Int?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([appId, isActive])\n  @@index([category])\n  @@index([platform])\n}\n\n// --- Content Uniqueness Pipeline (Track F) ---\n// Per-platform уникализированные варианты видео. Кеширование по paramsHash:\n// одинаковые параметры → один файл, повторный uniqify бесплатен.\n// Disclaimer: сервис меняет только file hash + base metadata, не обходит\n// perceptual hashing TikTok/Meta. Реальная защита от детектирования —\n// творческая (новый текст хук/CTA, монтажа и т.д.), а не техническая.\n\nmodel VideoUniqueVariant {\n  id          String   @id @default(cuid())\n  videoId     Int\n  video       Video    @relation(fields: [videoId], references: [id], onDelete: Cascade)\n  // Platform enum (tiktok | instagram | youtube). В API endpoint пока разрешаем\n  // только 'tiktok' и 'youtube', instagram → 400. Enum целиком оставляем для\n  // расширяемости без новой миграции.\n  platform    Platform\n  // Хэш сериализованных параметров uniqify (sha256 от JSON.stringify({crf, brightness, ...})).\n  // Сужаем до 16 hex для удобства имени файла.\n  paramsHash  String\n  // Полные параметры (UniqifyParams) — для отладки и UI «как уникализировано».\n  paramsJson  Json\n  // Относительный путь от storage/uploads, формат: `unique-variants/<videoId>/<platform>_<hash>.mp4`.\n  filePath    String\n  // Публичный URL: `/api/files/unique-variants/<videoId>/<platform>_<hash>.mp4`.\n  fileUrl     String\n  // SHA-256 содержимого готового файла. Главный sanity-check: должен отличаться от оригинала.\n  fileHash    String\n  durationSec Float\n  fileSize    Int\n  // GCS persistent storage: `zavodcamp/unique-variants/{videoId}/{platform}_{paramsHash}.mp4`.\n  // filePath/fileUrl остаются для backward compat.\n  storageKey  String?\n  createdAt   DateTime @default(now())\n\n  @@unique([videoId, platform, paramsHash])\n  @@index([videoId])\n}\n\n// --- Caption Generator (per-platform метаданные для публикации) ---\n// Создаётся CaptionGenerator-нодой pipeline'а или вручную через UI.\n// Один Caption на (videoId, platform). При approvedAt != null Upload\n// executor подменит placeholder title/description/hashtags на эти значения.\n//\n// fitsLimits — снимок прохождения validateCaption на момент создания/правки.\n// Если оператор отредактирует поля так, что лимит превышен — fitsLimits=false\n// и UI покажет предупреждение, approve будет заблокирован.\n\nmodel Caption {\n  id      String @id @default(cuid())\n  videoId Int\n  video   Video  @relation(fields: [videoId], references: [id], onDelete: Cascade)\n\n  platform    Platform\n  title       String\n  description String?\n  hashtags    String[]\n\n  // Validation snapshot (актуализируется при каждой правке)\n  charsTitle         Int\n  charsHashtagsTotal Int\n  fitsLimits         Boolean @default(true)\n\n  // Generation context\n  modelVersion   String\n  promptVersion  String @default(\"v1\")\n  generationCost Float?\n  generatedById  Int? // user или null если pipeline\n\n  // Pipeline tracking (если caption создан в рамках pipeline)\n  runId      Int?\n  pipelineId Int?\n\n  // Подтверждение оператором — Upload подменяет поля только при approvedAt != null\n  approvedAt   DateTime?\n  approvedById Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([videoId, platform])\n  @@index([videoId])\n  @@index([runId, pipelineId])\n}\n",
